contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // run takes an amount to forward to c.go; contract must have enough balance to send it
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient test balance");

        // observe owner before the call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        // make the state-changing call as a top-level statement
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe owner after the call
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // General invariant: the owner never changes as a result of calling go (regardless of revert)
        assert(ownerAfter == ownerBefore);
    }

    // accept ETH forwarded to this test contract
    receive() external payable {}
}

